window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3a9d0586cfbd05bc"]={"versions": [{"id": "FIG-3a9d0586cfbd05bc", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (M2-Metamodell-Ausschnitt der AUTOSAR Template-Spezifikation).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Spezifikation des Blueprint-Musters (<em>Standardization Template</em>, TPS_STDT) für Modellelemente, die keine eigenständigen Paketierungselemente (<code>ARElement</code>) darstellen. Veranschaulicht anhand von Port-Prototypen die architektonische Entkopplung zwischen der standardisierten Vorlage (<code>PortPrototypeBlueprint</code>) und dem im Software-Component-Typ instanziierten Modellelement (<code>PortPrototype</code>) sowie deren formale Rückverfolgbarkeit via <code>BlueprintMapping</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metaklassen & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>AtpBlueprintMapping</code></strong> (<em>Metaklasse</em>):</li>\n<li>Abstrakter Ursprungsknoten für Mappings zwischen standardisierten Blueprints und konkreten Zielobjekten.</li>\n<li><strong><code>BlueprintMapping</code></strong> (<em>Metaklasse</em>):</li>\n<li>Konkrete Ausprägung zur Speicherung der Zuordnungsrelation in ARXML-Beschreibungsdateien.</li>\n<li><strong><code>AtpBlueprint</code></strong> (<em>Metaklasse, spezialisiert <code>Identifiable</code></em>):</li>\n<li>Abstraktes Konzept für standardisierte M1-Entwurfsvorlagen.</li>\n<li><strong><code>AtpBlueprintable</code></strong> (<em>Metaklasse, spezialisiert <code>Identifiable</code></em>):</li>\n<li>Abstraktes Konzept für Modellelemente, die konform zu einem Blueprint abgeleitet werden können.</li>\n<li><strong><code>PortPrototypeBlueprint</code></strong> (<em>Metaklasse, spezialisiert <code>AtpBlueprint</code>, <code>ARElement</code>, <code>AtpStructureElement</code></em>):</li>\n<li>Standalone-fähiges Entwurfsmuster für Software-Ports. Da ein gewöhnlicher Port nicht autonom auf Paktebene existieren kann, wird hier ein eigenständiges <code>ARElement</code> deklariert.</li>\n<li><strong><code>PortPrototype</code></strong> (<em>Metaklasse, spezialisiert <code>AtpBlueprintable</code>, <code>AtpPrototype</code></em>):</li>\n<li>Konkreter Port-Prototyp (<code>PPortPrototype</code>, <code>RPortPrototype</code>, <code>PRPortPrototype</code>) innerhalb eines SwComponentType-Kontexts.</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong>Generalisierungen (Vererbung):</strong></li>\n<li><code>BlueprintMapping</code> $\\rightarrow$ <code>AtpBlueprintMapping</code></li>\n<li><code>PortPrototypeBlueprint</code> $\\rightarrow$ <code>AtpBlueprint</code> (sowie Mehrfachvererbung/Rollen von <code>ARElement</code>, <code>AtpStructureElement</code>)</li>\n<li><code>PortPrototype</code> $\\rightarrow$ <code>AtpBlueprintable</code> (sowie <code>AtpPrototype</code>)</li>\n<li><strong>Assoziationen auf abstrakter Ebene (<code>AtpBlueprintMapping</code>):</strong></li>\n<li><code>+/atpBlueprint</code> [1]: Stereotypen <code>«atpAbstract,atpUriDef»</code> $\\rightarrow$ Verweist abstrakt/URI-basiert auf genau ein <code>AtpBlueprint</code>.</li>\n<li><code>+/atpBlueprintedElement</code> [1]: Stereotyp <code>«atpAbstract»</code> $\\rightarrow$ Verweist abstrakt auf genau ein <code>AtpBlueprintable</code>.</li>\n<li><strong>Neudefinitionen auf konkreter Ebene (<code>BlueprintMapping</code>):</strong></li>\n<li><code>+blueprint</code> [1] <code>{redefines atpBlueprint}</code> $\\rightarrow$ Konkrete Referenz auf das Blueprint (<code>PortPrototypeBlueprint</code> via <code>AtpBlueprint</code>).</li>\n<li><code>+derivedObject</code> [1] <code>{redefines atpBlueprintedElement}</code> $\\rightarrow$ Konkrete Referenz auf das abgeleitete Modellelement (<code>PortPrototype</code> via <code>AtpBlueprintable</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches M2-Metamodell existiert kein direktes Laufzeitverhalten im RTE- oder BSW-Stack (keine OS-Tasks, ISRs oder Det/Dem-Meldungen). Der dynamische Lebenszyklus greift zur Design-/Konfigurationszeit (AUTOSAR Methodik):</p>\n<ol class=\"fig-list\">\n<li><strong>Standardisierung / Blueprint-Definition (OEM/Konsortium):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Erstellung des <code>PortPrototypeBlueprint</code> als autonomes <code>ARElement</code> in einem ARXML-Katalog zur Festlegung standardisierter Schnittstelleneigenschaften (z. B. Port-Interface-Typ, Kommunikationssemantik).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Komponenten-Modellierung (Tier-1 / Applikationsentwickler):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Instanziierung eines konkreten <code>PortPrototype</code> als Kindelement eines <code>AtomicSwComponentType</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Traceability & Konformitäts-Bindung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Instanziierung eines <code>BlueprintMapping</code>.</li>\n<li>Setzen der Assoziationen <code>blueprint</code> $\\rightarrow$ <code>PortPrototypeBlueprint</code> und <code>derivedObject</code> $\\rightarrow$ <code>PortPrototype</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Modell-Validierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Validierungstools prüfen anhand des Mappings die Konformität des <code>PortPrototype</code> gegen die normativen Vorgaben des <code>PortPrototypeBlueprint</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Architektonische Trennung (<code>ARElement</code> vs. <code>AtpPrototype</code>):</strong></li>\n<li>Ein <code>PortPrototype</code> erbt von <code>AtpPrototype</code> und besitzt keine eigenständige Existenzberechtigung außerhalb eines Komponenten-Containers. Daher verbietet das Metamodell die direkte Verwendung von <code>PortPrototype</code> als Blueprint-Katalogelement.</li>\n<li>Entwickler/Modellierer müssen für standardisierte Port-Vorgaben zwingend die Wrapper-Metaklasse <code>PortPrototypeBlueprint</code> instanziieren (TPS_STDT_00041).</li>\n<li><strong>Rückverfolgbarkeit & Compliance (RS_STDT_00006, TPS_STDT_00072):</strong></li>\n<li>Das Vorhandensein eines <code>BlueprintMapping</code> erzwingt die semantische Übereinstimmung (z. B. Interface-Kompatibilität, Datenrichtungs-Semantik). Werkzeuge zur Konformitätsprüfung (Model Consistency Checker) brechen mit Fehlern ab, wenn deklarierte Redefinitionen (<code>blueprint</code>, <code>derivedObject</code>) inkonsistente Typdefinitionen referenzieren.</li>\n<li><strong>ARXML-Serialisierung:</strong></li>\n<li>Da <code>atpBlueprint</code> mit <code>«atpUriDef»</code> annotiert ist, unterstützt die Referenz standardisierte URI-Identifikatoren. Dies ermöglicht verteilte Kataloge, bei denen Blueprints als unveränderliche Vorgaben versioniert und über Package-Grenzen hinweg referenziert werden.</li>\n</ul>"}, {"id": "FIG-f7847ed63c513863", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (M2-Metamodell-Ausschnitt der AUTOSAR Template-Spezifikation).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Spezifikation des Blueprint-Musters (<em>Standardization Template</em>, TPS_STDT) für Modellelemente, die keine eigenständigen Paketierungselemente (<code>ARElement</code>) darstellen. Veranschaulicht anhand von Port-Prototypen die architektonische Entkopplung zwischen der standardisierten Vorlage (<code>PortPrototypeBlueprint</code>) und dem im Software-Component-Typ instanziierten Modellelement (<code>PortPrototype</code>) sowie deren formale Rückverfolgbarkeit via <code>BlueprintMapping</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metaklassen & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>AtpBlueprintMapping</code></strong> (<em>Metaklasse</em>):</li>\n<li>Abstrakter Ursprungsknoten für Mappings zwischen standardisierten Blueprints und konkreten Zielobjekten.</li>\n<li><strong><code>BlueprintMapping</code></strong> (<em>Metaklasse</em>):</li>\n<li>Konkrete Ausprägung zur Speicherung der Zuordnungsrelation in ARXML-Beschreibungsdateien.</li>\n<li><strong><code>AtpBlueprint</code></strong> (<em>Metaklasse, spezialisiert <code>Identifiable</code></em>):</li>\n<li>Abstraktes Konzept für standardisierte M1-Entwurfsvorlagen.</li>\n<li><strong><code>AtpBlueprintable</code></strong> (<em>Metaklasse, spezialisiert <code>Identifiable</code></em>):</li>\n<li>Abstraktes Konzept für Modellelemente, die konform zu einem Blueprint abgeleitet werden können.</li>\n<li><strong><code>PortPrototypeBlueprint</code></strong> (<em>Metaklasse, spezialisiert <code>AtpBlueprint</code>, <code>ARElement</code>, <code>AtpStructureElement</code></em>):</li>\n<li>Standalone-fähiges Entwurfsmuster für Software-Ports. Da ein gewöhnlicher Port nicht autonom auf Paktebene existieren kann, wird hier ein eigenständiges <code>ARElement</code> deklariert.</li>\n<li><strong><code>PortPrototype</code></strong> (<em>Metaklasse, spezialisiert <code>AtpBlueprintable</code>, <code>AtpPrototype</code></em>):</li>\n<li>Konkreter Port-Prototyp (<code>PPortPrototype</code>, <code>RPortPrototype</code>, <code>PRPortPrototype</code>) innerhalb eines SwComponentType-Kontexts.</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong>Generalisierungen (Vererbung):</strong></li>\n<li><code>BlueprintMapping</code> $\\rightarrow$ <code>AtpBlueprintMapping</code></li>\n<li><code>PortPrototypeBlueprint</code> $\\rightarrow$ <code>AtpBlueprint</code> (sowie Mehrfachvererbung/Rollen von <code>ARElement</code>, <code>AtpStructureElement</code>)</li>\n<li><code>PortPrototype</code> $\\rightarrow$ <code>AtpBlueprintable</code> (sowie <code>AtpPrototype</code>)</li>\n<li><strong>Assoziationen auf abstrakter Ebene (<code>AtpBlueprintMapping</code>):</strong></li>\n<li><code>+/atpBlueprint</code> [1]: Stereotypen <code>«atpAbstract,atpUriDef»</code> $\\rightarrow$ Verweist abstrakt/URI-basiert auf genau ein <code>AtpBlueprint</code>.</li>\n<li><code>+/atpBlueprintedElement</code> [1]: Stereotyp <code>«atpAbstract»</code> $\\rightarrow$ Verweist abstrakt auf genau ein <code>AtpBlueprintable</code>.</li>\n<li><strong>Neudefinitionen auf konkreter Ebene (<code>BlueprintMapping</code>):</strong></li>\n<li><code>+blueprint</code> [1] <code>{redefines atpBlueprint}</code> $\\rightarrow$ Konkrete Referenz auf das Blueprint (<code>PortPrototypeBlueprint</code> via <code>AtpBlueprint</code>).</li>\n<li><code>+derivedObject</code> [1] <code>{redefines atpBlueprintedElement}</code> $\\rightarrow$ Konkrete Referenz auf das abgeleitete Modellelement (<code>PortPrototype</code> via <code>AtpBlueprintable</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches M2-Metamodell existiert kein direktes Laufzeitverhalten im RTE- oder BSW-Stack (keine OS-Tasks, ISRs oder Det/Dem-Meldungen). Der dynamische Lebenszyklus greift zur Design-/Konfigurationszeit (AUTOSAR Methodik):</p>\n<ol class=\"fig-list\">\n<li><strong>Standardisierung / Blueprint-Definition (OEM/Konsortium):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Erstellung des <code>PortPrototypeBlueprint</code> als autonomes <code>ARElement</code> in einem ARXML-Katalog zur Festlegung standardisierter Schnittstelleneigenschaften (z. B. Port-Interface-Typ, Kommunikationssemantik).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Komponenten-Modellierung (Tier-1 / Applikationsentwickler):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Instanziierung eines konkreten <code>PortPrototype</code> als Kindelement eines <code>AtomicSwComponentType</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Traceability & Konformitäts-Bindung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Instanziierung eines <code>BlueprintMapping</code>.</li>\n<li>Setzen der Assoziationen <code>blueprint</code> $\\rightarrow$ <code>PortPrototypeBlueprint</code> und <code>derivedObject</code> $\\rightarrow$ <code>PortPrototype</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Modell-Validierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Validierungstools prüfen anhand des Mappings die Konformität des <code>PortPrototype</code> gegen die normativen Vorgaben des <code>PortPrototypeBlueprint</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Architektonische Trennung (<code>ARElement</code> vs. <code>AtpPrototype</code>):</strong></li>\n<li>Ein <code>PortPrototype</code> erbt von <code>AtpPrototype</code> und besitzt keine eigenständige Existenzberechtigung außerhalb eines Komponenten-Containers. Daher verbietet das Metamodell die direkte Verwendung von <code>PortPrototype</code> als Blueprint-Katalogelement.</li>\n<li>Entwickler/Modellierer müssen für standardisierte Port-Vorgaben zwingend die Wrapper-Metaklasse <code>PortPrototypeBlueprint</code> instanziieren (TPS_STDT_00041).</li>\n<li><strong>Rückverfolgbarkeit & Compliance (RS_STDT_00006, TPS_STDT_00072):</strong></li>\n<li>Das Vorhandensein eines <code>BlueprintMapping</code> erzwingt die semantische Übereinstimmung (z. B. Interface-Kompatibilität, Datenrichtungs-Semantik). Werkzeuge zur Konformitätsprüfung (Model Consistency Checker) brechen mit Fehlern ab, wenn deklarierte Redefinitionen (<code>blueprint</code>, <code>derivedObject</code>) inkonsistente Typdefinitionen referenzieren.</li>\n<li><strong>ARXML-Serialisierung:</strong></li>\n<li>Da <code>atpBlueprint</code> mit <code>«atpUriDef»</code> annotiert ist, unterstützt die Referenz standardisierte URI-Identifikatoren. Dies ermöglicht verteilte Kataloge, bei denen Blueprints als unveränderliche Vorgaben versioniert und über Package-Grenzen hinweg referenziert werden.</li>\n</ul>"}, {"id": "FIG-7e9c473047fe21ff", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (M2-Metamodell-Ausschnitt der AUTOSAR Template-Spezifikation).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Spezifikation des Blueprint-Musters (<em>Standardization Template</em>, TPS_STDT) für Modellelemente, die keine eigenständigen Paketierungselemente (<code>ARElement</code>) darstellen. Veranschaulicht anhand von Port-Prototypen die architektonische Entkopplung zwischen der standardisierten Vorlage (<code>PortPrototypeBlueprint</code>) und dem im Software-Component-Typ instanziierten Modellelement (<code>PortPrototype</code>) sowie deren formale Rückverfolgbarkeit via <code>BlueprintMapping</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metaklassen & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>AtpBlueprintMapping</code></strong> (<em>Metaklasse</em>):</li>\n<li>Abstrakter Ursprungsknoten für Mappings zwischen standardisierten Blueprints und konkreten Zielobjekten.</li>\n<li><strong><code>BlueprintMapping</code></strong> (<em>Metaklasse</em>):</li>\n<li>Konkrete Ausprägung zur Speicherung der Zuordnungsrelation in ARXML-Beschreibungsdateien.</li>\n<li><strong><code>AtpBlueprint</code></strong> (<em>Metaklasse, spezialisiert <code>Identifiable</code></em>):</li>\n<li>Abstraktes Konzept für standardisierte M1-Entwurfsvorlagen.</li>\n<li><strong><code>AtpBlueprintable</code></strong> (<em>Metaklasse, spezialisiert <code>Identifiable</code></em>):</li>\n<li>Abstraktes Konzept für Modellelemente, die konform zu einem Blueprint abgeleitet werden können.</li>\n<li><strong><code>PortPrototypeBlueprint</code></strong> (<em>Metaklasse, spezialisiert <code>AtpBlueprint</code>, <code>ARElement</code>, <code>AtpStructureElement</code></em>):</li>\n<li>Standalone-fähiges Entwurfsmuster für Software-Ports. Da ein gewöhnlicher Port nicht autonom auf Paketebene existieren kann, wird hier ein eigenständiges <code>ARElement</code> deklariert.</li>\n<li><strong><code>PortPrototype</code></strong> (<em>Metaklasse, spezialisiert <code>AtpBlueprintable</code>, <code>AtpPrototype</code></em>):</li>\n<li>Konkreter Port-Prototyp (<code>PPortPrototype</code>, <code>RPortPrototype</code>, <code>PRPortPrototype</code>) innerhalb eines SwComponentType-Kontexts.</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong>Generalisierungen (Vererbung):</strong></li>\n<li><code>BlueprintMapping</code> $\\rightarrow$ <code>AtpBlueprintMapping</code></li>\n<li><code>PortPrototypeBlueprint</code> $\\rightarrow$ <code>AtpBlueprint</code> (sowie Mehrfachvererbung/Rollen von <code>ARElement</code>, <code>AtpStructureElement</code>)</li>\n<li><code>PortPrototype</code> $\\rightarrow$ <code>AtpBlueprintable</code> (sowie <code>AtpPrototype</code>)</li>\n<li><strong>Assoziationen auf abstrakter Ebene (<code>AtpBlueprintMapping</code>):</strong></li>\n<li><code>+/atpBlueprint</code> [1]: Stereotypen <code>«atpAbstract,atpUriDef»</code> $\\rightarrow$ Verweist abstrakt/URI-basiert auf genau ein <code>AtpBlueprint</code>.</li>\n<li><code>+/atpBlueprintedElement</code> [1]: Stereotyp <code>«atpAbstract»</code> $\\rightarrow$ Verweist abstrakt auf genau ein <code>AtpBlueprintable</code>.</li>\n<li><strong>Neudefinitionen auf konkreter Ebene (<code>BlueprintMapping</code>):</strong></li>\n<li><code>+blueprint</code> [1] <code>{redefines atpBlueprint}</code>: Stereotyp <code>«atpIdentityContributor»</code> $\\rightarrow$ Konkrete Referenz auf das Blueprint (<code>PortPrototypeBlueprint</code> via <code>AtpBlueprint</code>), trägt zur Identität des Mappings bei.</li>\n<li><code>+derivedObject</code> [1] <code>{redefines atpBlueprintedElement}</code>: Stereotyp <code>«atpIdentityContributor»</code> $\\rightarrow$ Konkrete Referenz auf das abgeleitete Modellelement (<code>PortPrototype</code> via <code>AtpBlueprintable</code>), trägt zur Identität des Mappings bei.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches M2-Metamodell existiert kein direktes Laufzeitverhalten im RTE- oder BSW-Stack (keine OS-Tasks, ISRs oder Det/Dem-Meldungen). Der dynamische Lebenszyklus greift zur Design-/Konfigurationszeit (AUTOSAR Methodik):</p>\n<ol class=\"fig-list\">\n<li><strong>Standardisierung / Blueprint-Definition (OEM/Konsortium):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Erstellung des <code>PortPrototypeBlueprint</code> als autonomes <code>ARElement</code> in einem ARXML-Katalog zur Festlegung standardisierter Schnittstelleneigenschaften (z. B. Port-Interface-Typ, Kommunikationssemantik).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Komponenten-Modellierung (Tier-1 / Applikationsentwickler):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Instanziierung eines konkreten <code>PortPrototype</code> als Kindelement eines <code>AtomicSwComponentType</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Traceability & Konformitäts-Bindung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Instanziierung eines <code>BlueprintMapping</code>.</li>\n<li>Setzen der Assoziationen <code>blueprint</code> $\\rightarrow$ <code>PortPrototypeBlueprint</code> und <code>derivedObject</code> $\\rightarrow$ <code>PortPrototype</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Modell-Validierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Validierungstools prüfen anhand des Mappings die Konformität des <code>PortPrototype</code> gegen die normativen Vorgaben des <code>PortPrototypeBlueprint</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Architektonische Trennung (<code>ARElement</code> vs. <code>AtpPrototype</code>):</strong></li>\n<li>Ein <code>PortPrototype</code> erbt von <code>AtpPrototype</code> und besitzt keine eigenständige Existenzberechtigung außerhalb eines Komponenten-Containers. Daher verbietet das Metamodell die direkte Verwendung von <code>PortPrototype</code> als Blueprint-Katalogelement.</li>\n<li>Entwickler/Modellierer müssen für standardisierte Port-Vorgaben zwingend die Wrapper-Metaklasse <code>PortPrototypeBlueprint</code> instanziieren (TPS_STDT_00041).</li>\n<li><strong>Rückverfolgbarkeit & Compliance (RS_STDT_00006, TPS_STDT_00072):</strong></li>\n<li>Das Vorhandensein eines <code>BlueprintMapping</code> erzwingt die semantische Übereinstimmung (z. B. Interface-Kompatibilität, Datenrichtungs-Semantik). Werkzeuge zur Konformitätsprüfung (Model Consistency Checker) brechen mit Fehlern ab, wenn deklarierte Redefinitionen (<code>blueprint</code>, <code>derivedObject</code>) inkonsistente Typdefinitionen referenzieren.</li>\n<li><strong>ARXML-Serialisierung:</strong></li>\n<li>Da <code>atpBlueprint</code> mit <code>«atpUriDef»</code> annotiert ist, unterstützt die Referenz standardisierte URI-Identifikatoren. Dies ermöglicht verteilte Kataloge, bei denen Blueprints als unveränderliche Vorgaben versioniert und über Package-Grenzen hinweg referenziert werden.</li>\n</ul>"}], "trans": [{"from": "FIG-3a9d0586cfbd05bc", "to": "FIG-f7847ed63c513863", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-f7847ed63c513863", "to": "FIG-7e9c473047fe21ff", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Assoziation <code>blueprint</code> von <code>BlueprintMapping</code>: Ergänzung des Stereotyps <code>«atpIdentityContributor»</code>.</li>\n<li>Assoziation <code>derivedObject</code> von <code>BlueprintMapping</code>: Ergänzung des Stereotyps <code>«atpIdentityContributor»</code>.</li>\n</ul>"}]};
